                .andExpect(status().isOk());

        mockMvc.perform(get("/api/device-sessions/{d}/{s}", "dev-1", "sess-9"))
                .andExpect(jsonPath("$.watermark").value(1));
        mockMvc.perform(get("/api/device-sessions/{d}/{s}", "dev-1", "sess-10"))
                .andExpect(jsonPath("$.watermark").value(1));
    }

